export const upperLimbQuestionIds: Record<string, Set<string>> = Object.fromEntries(
  [...Object.entries(upperLimbPracticeBanks), ...Object.entries(upperLimbVerificationBanks)].map(([id, bank]) => [id, new Set(bank.map((question) => question.id))])
);

export function getUpperLimbPracticeBank(studyId?: string, projectionId?: string) {
  return upperLimbPracticeBanks[`${studyId}-${projectionId}`] ?? [];
}

export function getUpperLimbVerificationBank(studyId?: string) {
  return upperLimbVerificationBanks[`${studyId}-verification`] ?? [];
}
